import React, { useRef } from 'react';

import { useTooltipEventListeners } from '../../../core/hooks/useTooltipEventListeners.js';
import { TooltipItem } from '../../../core/types/tooltip.js';
import { MeterBarTooltip } from '../../shared/components/meter-bar-tooltip/MeterBarTooltip.js';
import { useFormatter } from '../../shared/context/FormatterContext.js';
import { useMultiMeterBarChartTooltipData } from '../context/MultiMeterBarChartTooltipContext.js';
import {
  useMultiMeterBarTooltipState,
  useMultiMeterBarVisibleSegmentsState,
} from '../hooks/store/selectors.js';
import { useTooltip } from '../hooks/useTooltip.js';

export const MultiMeterBarChartTooltip = () => {
  const tooltipRef = useRef<HTMLDivElement>(null);
  const { pinned, visible, content } = useMultiMeterBarTooltipState();
  const visibleSegments = useMultiMeterBarVisibleSegmentsState();
  const { tooltipConfig } = useMultiMeterBarChartTooltipData();
  const isSharedTooltip = tooltipConfig.variant === 'shared';
  const { hideTooltip } = useTooltip();

  useTooltipEventListeners(tooltipRef, pinned, hideTooltip);
  const { formatter } = useFormatter();

  if (!visible) {
    return null;
  }

  const contentWithFormattedValue: TooltipItem | undefined = content && {
    ...content,
    values: content.values!.map((value) => formatter(+value)),
  };

  const getItemsForVariant = (): TooltipItem[] => {
    const selectedItem: TooltipItem[] = contentWithFormattedValue
      ? [contentWithFormattedValue]
      : [];

    if (isSharedTooltip) {
      const allItems: TooltipItem[] = visibleSegments.map((item) => ({
        id: item.id,
        name: item.name ?? '',
        values: [formatter(item.value)],
        color: { Default: item.color },
      }));

      return allItems;
    }

    return selectedItem;
  };

  return (
    <MeterBarTooltip
      ref={tooltipRef}
      items={getItemsForVariant()}
      isPinned={pinned}
    />
  );
};
